values
  ('0e5ef8d6-68de-536c-ad04-505d576a3494', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'medium',
   $q$Why is it significant that Wendell considered the second notebook "a hobby, not work"?$q$, $q$[{"text":"It shows that Wendell, too, first undervalued local knowledge, which makes its later place in the atlas more meaningful.","is_correct":true},{"text":"It shows that Wendell was lazy and did not take the survey seriously.","is_correct":false,"misconception_token":"misreads-character"},{"text":"It explains why Holt was angry and frowned when he read the field book.","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"It proves that the local names had no value until Holt approved them.","is_correct":false,"misconception_token":"overstates-claim"}]$q$::jsonb, $q$It shows that Wendell, too, first undervalued local knowledge, which makes its later place in the atlas more meaningful.$q$, $q$Even Wendell assumes the names are not real work, so their eventual inclusion shows a shift in what counts as knowledge. He finishes the eastern section alone, so he is not lazy.$q$, 'draft', '640cdf0e-ec79-5269-8460-e6e48ea6f1a2')
