values
  ('a1d9d24c-12c1-5f37-9f65-6895218584a7', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'hard',
   $q$How do Freya's handshake and Marisol's line "I regret losing. I don't regret how" together develop the passage's themes?$q$, $q$[{"text":"The handshake shows respect from a rival, and the line shows Marisol holding both real loss and pride in her conduct.","is_correct":true},{"text":"They show that Freya feels guilty because she knows she did not deserve the medal.","is_correct":false,"misconception_token":"misreads-character"},{"text":"They show that Marisol no longer cares about winning now that she has earned respect.","is_correct":false,"misconception_token":"overstates-claim"},{"text":"They show that both fencers think the final result was unfair and should be changed.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$The handshake shows respect from a rival, and the line shows Marisol holding both real loss and pride in her conduct.$q$, $q$Freya publicly honors Marisol, and Marisol admits the loss hurts while standing by her choice, so the cost of integrity and the respect it earns coexist. She says "I regret losing," so she still cares about winning.$q$, 'draft', '66abf76b-c2d5-521f-bd75-08325eac49d5')
