  ('313330d7-86d3-5806-a460-cc2b6369e35b', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'hard',
   $q$How do the themes of leaving and inherited tradition build on each other by the final stanza?$q$, $q$[{"text":"Because the grandmother taught the route, the speaker can leave without losing home, since the way back is already learned.","is_correct":true},{"text":"The speaker decides that leaving would betray the tradition and chooses to stay home.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The tradition ends because the grandmother can no longer drive to the river.","is_correct":false,"misconception_token":"ignores-ending"},{"text":"The speaker realizes that cranes and people have nothing in common after all.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Because the grandmother taught the route, the speaker can leave without losing home, since the way back is already learned.$q$, $q$The final lines link belonging that does not "keep" you with a grandmother who "had been teaching me the route all along," so the inherited ritual makes leaving bearable. The speaker is still leaving, so staying home contradicts the poem.$q$, 'draft', 'b5945d61-2ba0-5c29-8d89-fade7d73d655')
