values
  ('68c8f29b-4334-54a7-b31d-f5cb5ab1704f', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the fable?$q$, $q$[{"text":"Riddles are the best way to teach young learners to think for themselves.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Marmots must choose dry burrows to survive the mountain winter.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Knowledge kept to make others need us isolates us, while shared knowledge builds stronger bonds.","is_correct":true},{"text":"Old animals should let the young make every decision for the group.","is_correct":false,"misconception_token":"overstates-claim"}]$q$::jsonb, $q$Knowledge kept to make others need us isolates us, while shared knowledge builds stronger bonds.$q$, $q$Teska hoards knowledge to be needed, but sharing it plainly creates a shared map and more visits. Her riddles left many young marmots "wet and shivering," so the fable does not praise them.$q$, 'draft', '14de3638-bd5a-502a-a9c5-697b5d2d8f23')
